begin(
  x := 0,
  do(x < 5, x := x + 1),
  if(x = 5,
    begin(y := x * 2, y),
    -1
  )
)

begin(
  f := fn({x},
    {
      if(x < 0, return("negative")),
      if(x = 0, return("zero")),
      return("positive")
    }
  ),
  { -5, 0, 5 }.map(f)
)

